export type Cell = [number, number];

const cellKey = (cell: Cell): string => `${cell[0]},${cell[1]}`;

const neighborsOf = (cell: Cell): Cell[] => {
  const [x, y] = cell;
  const offsets = [-1, 0, 1];
  return offsets.flatMap((dx) =>
    offsets
      .filter((dy) => dx !== 0 || dy !== 0)
      .map((dy): Cell => [x + dx, y + dy]),
  );
};

type Candidate = { cell: Cell; liveNeighbors: number };

const countLiveNeighbors = (cells: Cell[]): Map<string, Candidate> => {
  const tally = new Map<string, Candidate>();
  cells.forEach((cell) =>
    neighborsOf(cell).forEach((neighbor) => {
      const seen = tally.get(cellKey(neighbor)) ?? { cell: neighbor, liveNeighbors: 0 };
      tally.set(cellKey(neighbor), { ...seen, liveNeighbors: seen.liveNeighbors + 1 });
    }),
  );
  return tally;
};

export const nextGeneration = (cells: Cell[]): Cell[] => {
  const living = new Set(cells.map(cellKey));

  return [...countLiveNeighbors(cells).values()]
    .filter(({ cell, liveNeighbors }) =>
      living.has(cellKey(cell))
        ? liveNeighbors === 2 || liveNeighbors === 3
        : liveNeighbors === 3,
    )
    .map(({ cell }) => cell);
};

