1	export type Cell = [number, number];
2	
3	const toKey = (cell: Cell): string => `${cell[0]},${cell[1]}`;
4	
5	const fromKey = (key: string): Cell => {
6	  const [x, y] = key.split(",").map(Number);
7	  return [x, y];
8	};
9	
10	const neighborsOf = (cell: Cell): Cell[] => {
11	  const [x, y] = cell;
12	  const offsets = [-1, 0, 1];
13	  return offsets.flatMap((dx) =>
14	    offsets
15	      .filter((dy) => dx !== 0 || dy !== 0)
16	      .map((dy): Cell => [x + dx, y + dy]),
17	  );
18	};
19	
20	const liveNeighborCounts = (cells: Cell[]): Map<string, number> => {
21	  const counts = new Map<string, number>();
22	  cells.forEach((cell) =>
23	    neighborsOf(cell).forEach((neighbor) => {
24	      const key = toKey(neighbor);
25	      counts.set(key, (counts.get(key) ?? 0) + 1);
26	    }),
27	  );
28	  return counts;
29	};
