31	export const nextGeneration = (cells: Cell[]): Cell[] => {
32	  const living = new Set(cells.map(toKey));
33	
34	  return [...liveNeighborCounts(cells)]
35	    .filter(([key, liveNeighbors]) =>
36	      living.has(key) ? liveNeighbors === 2 || liveNeighbors === 3 : liveNeighbors === 3,
37	    )
